const overrides = {};

function add(id, question, answer, sourceKey, asOf = null) {
  const [source, sourceLink] = SOURCES[sourceKey];
  overrides[id] = {
    question,
    answer,
    source,
    source_link: sourceLink,
    ...(asOf ? { as_of: asOf } : {}),
    verified: true,
  };
}

function addMany(ids, specs) {
  if (ids.length !== specs.length) {
    throw new Error(`Verified-card source mismatch: ${ids.length} ids for ${specs.length} specifications`);
  }
  ids.forEach((id, index) => add(id, ...specs[index]));
}

// Core finance and market-awareness cards.
add('gk_rbi_001',
  'What is the difference between the RBI repo rate, Standing Deposit Facility rate and fixed reverse-repo rate?',
  'The repo rate is the rate at which the RBI supplies overnight liquidity to banks against eligible collateral. The Standing Deposit Facility (SDF) is the uncollateralised rate at which banks can place surplus funds with the RBI and is the operating floor of the liquidity-adjustment corridor. The fixed reverse-repo rate still exists in the published rate table, but the SDF replaced it as the normal floor in April 2022. On 27 July 2026 the three rates were 5.25%, 5.00% and 3.35%, respectively.',
  'RBI_CURRENT', '27 July 2026');
add('gk_rbi_002',
  'What are CRR and SLR, and what were their RBI-prescribed levels on 27 July 2026?',
  'Cash Reserve Ratio (CRR) is the share of a bank’s net demand and time liabilities that must be held as cash with the RBI; it earns no interest. Statutory Liquidity Ratio (SLR) is the share maintained in liquid assets such as cash, gold and approved government securities. On 27 July 2026 the RBI listed CRR at 3.00% and SLR at 18.00%. A higher requirement generally reduces funds available for lending, although the transmission depends on system liquidity and credit demand.',
  'RBI_CURRENT', '27 July 2026');
add('gk_bank_001',
  'When does a term loan become a non-performing asset under RBI norms, and what happens next?',
  'A term loan generally becomes a non-performing asset when interest or principal remains overdue for more than 90 days. Banks then stop recognising unrealised interest as income and classify the exposure by time and recoverability—sub-standard, doubtful or loss asset—while making progressively larger provisions. The 90-day test is not a statement that recovery is impossible; it is an accounting and prudential trigger designed to recognise credit deterioration early.',
  'RBI_IBC');
add('gk_bank_002',
  'What is CASA, and why does a high CASA ratio usually help a bank?',
  'CASA means current-account and savings-account deposits. The CASA ratio is CASA deposits divided by total deposits. Current accounts normally pay no interest and savings accounts usually cost less than term deposits, so a higher CASA mix can reduce a bank’s average funding cost and support net interest margin. It is not automatically “better”: unstable balances, expensive customer acquisition or weak loan pricing can offset the benefit.',
  'RBI_CURRENT');
add('gk_reg_001',
  'Which Indian regulators oversee banking, securities, insurance, pensions and the GIFT IFSC?',
  'The RBI regulates banks and most payment and monetary-system activity; SEBI regulates the securities market and its intermediaries; IRDAI regulates insurance; PFRDA regulates the National Pension System and pension intermediaries; and IFSCA is the unified regulator for financial products, services and institutions in India’s International Financial Services Centres. Their mandates can overlap at product boundaries, so the legal form and place of business determine the lead regulator.',
  'SEBI');
add('gk_idx_001',
  'How do the Nifty 50 and S&P BSE Sensex differ?',
  'The Nifty 50 is NSE’s free-float market-capitalisation-weighted index of 50 large, liquid companies, while the Sensex is BSE’s free-float market-capitalisation-weighted index of 30 established companies. They use different constituents, base dates and index values, but both are broad large-cap Indian equity benchmarks. On 24 July 2026 the RBI market snapshot recorded the Nifty 50 at 23,767.45 and the Sensex at 76,059.77.',
  'RBI_CURRENT', '24 July 2026');
add('gk_inv_001',
  'How is an exchange-traded fund different from a conventional open-ended mutual fund?',
  'An ETF holds a portfolio according to its mandate but trades intraday on an exchange, so investors need a trading account and face bid–ask spreads; authorised participants create or redeem large blocks that help keep price near NAV. A conventional open-ended fund is bought or redeemed with the fund house at the applicable end-of-day NAV. Either can be active or passive, although most ETFs are index-tracking. Costs, tracking difference, liquidity and taxes all matter.',
  'SEBI');
add('gk_tax_001',
  'What is India’s GST, and what rate structure took effect after the 56th GST Council decisions?',
  'Goods and Services Tax is a destination-based indirect tax collected through Central GST, State/UT GST and Integrated GST, with input-tax credit intended to prevent tax-on-tax. From 22 September 2025 the principal rate structure was rationalised to 5% and 18%, alongside exempt or nil-rated supplies and a special 40% rate for specified luxury or demerit goods. The applicable rate is product-specific; calling GST a single flat tax is incorrect.',
  'GST', '22 September 2025');

addMany(
  ['ca_mac_001', 'ca_mac_002', 'ca_mac_003', 'ca_gk_001', 'ca_gk_002', 'gk_his_001', 'gk_his_002',
    'val_2026_001', 'val_2026_002', 'val_2026_003', 'val_2026_004', 'val_2026_005',
    'ca_val_006', 'ca_val_007', 'ca_val_008', 'ca_val_009', 'ca_val_010'],
  [
    ['What policy rate did the RBI publish on 27 July 2026, and what does that rate control?',
      'The RBI policy repo rate was 5.25%. It is the price at which eligible banks can borrow overnight funds from the RBI against collateral and is the anchor for the monetary-policy operating corridor. The SDF floor was 5.00% and the MSF/Bank Rate ceiling was 5.50%. These administered rates influence, but do not mechanically set, every deposit, loan or bond yield.', 'RBI_CURRENT', '27 July 2026'],
    ['What was the U.S. federal-funds target range after the 17 June 2026 FOMC meeting?',
      'The Federal Open Market Committee maintained the target range at 3.50%–3.75%. It also continued its balance-sheet policy and said inflation remained elevated, with supply disruptions—especially energy—adding uncertainty. The target is a range for the overnight interbank rate, not a consumer borrowing rate; Treasury yields and mortgage rates incorporate expectations, term premium and credit or prepayment risk.', 'FED', '17 June 2026'],
    ['How do repo, SDF and MSF form the RBI policy corridor?',
      'The repo rate is the policy anchor. The SDF rate is normally set below repo and provides the floor because banks can deposit surplus liquidity without collateral; the Marginal Standing Facility rate is above repo and provides an overnight collateralised backstop, forming the ceiling. On 27 July 2026 the corridor was 5.00%–5.50% around a 5.25% repo rate.', 'RBI_CURRENT', '27 July 2026'],
    ['What does SEBI do, and what does it not guarantee?',
      'SEBI protects investors and regulates and develops India’s securities market. It registers and supervises intermediaries, regulates exchanges and listed-company disclosures, frames mutual-fund and takeover rules, investigates misconduct and can issue directions or penalties within its statutory powers. Registration or approval does not guarantee an investment’s return, credit quality or suitability; market and issuer risk remain with the investor.', 'SEBI'],
    ['What happened to Long-Term Capital Management in 1998, and why is it still taught?',
      'LTCM was a highly leveraged hedge fund whose relative-value trades suffered severe losses after Russia’s 1998 default and the global flight to liquidity. Because its positions were large and intertwined with major dealers, the Federal Reserve Bank of New York facilitated—not funded—a private-sector recapitalisation by creditor institutions. The case shows that apparently hedged convergence trades can combine leverage, liquidity risk, crowded positioning and model error into systemic stress.', 'FED'],
    ['What did the U.S. Glass–Steagall provisions separate, and what changed in 1999?',
      'The Banking Act of 1933 included provisions separating key commercial-banking and securities activities and created federal deposit insurance. The Gramm–Leach–Bliley Act of 1999 removed important affiliation barriers, allowing financial holding companies to own commercial-banking, securities and insurance businesses subject to regulation. It did not abolish every restriction on banks’ securities activity, so “Glass–Steagall was completely repealed” is too broad.', 'FED'],
    ['Why was the U.S. Securities and Exchange Commission created?',
      'Congress created the SEC through the Securities Exchange Act of 1934 after the market abuses exposed around the 1929 crash. Its mandate includes enforcing federal securities laws, overseeing exchanges and broker-dealers, requiring public-company disclosure and protecting investors while facilitating capital formation. The SEC is the closest U.S. analogue to SEBI, but the two operate under different statutes and market structures.', 'SEBI'],
    ['What were India’s two headline equity indices in the latest RBI market snapshot available on 27 July 2026?',
      'For 24 July 2026, the RBI market snapshot recorded the S&P BSE Sensex at 76,059.77 and the Nifty 50 at 23,767.45. A level is not a percentage return: performance must be measured against a specified earlier close and should account for dividends if a total-return comparison is intended.', 'RBI_CURRENT', '24 July 2026'],
    ['What was the RBI reference rate for the rupee against the U.S. dollar on 27 July 2026?',
      'At 1:00 p.m. on 27 July 2026, the RBI reference rate was ₹96.1856 per U.S. dollar. Because the quote is INR per USD, a higher number means the rupee is weaker and a lower number means it is stronger. This is a dated benchmark reference rate, not a promise that every bank, card network or dealer transacted at exactly that level.', 'RBI_CURRENT', '27 July 2026'],
    ['What benchmark Indian government-bond yield did the RBI publish on 24 July 2026?',
      'The RBI market snapshot showed the 6.94% Government Security 2036 at a yield of 6.8282% on 24 July 2026. The bond’s 6.94% coupon is fixed, while its yield changes with market price and remaining cash flows. Yield below coupon generally means the bond trades above par, subject to settlement and accrued-interest conventions.', 'RBI_CURRENT', '24 July 2026'],
    ['What was India’s CPI inflation rate in June 2026 under the new CPI series?',
      'India’s provisional combined CPI inflation was 4.38% year on year in June 2026 under the 2024=100 series. Rural inflation was 4.74%, urban inflation 3.92% and combined food inflation 5.32%. The comparison is year on year; it does not mean the price level rose 4.38% during June alone.', 'MOSPI_CPI', 'June 2026'],
    ['What was the Federal Reserve policy setting after its June 2026 meeting?',
      'The FOMC held the federal-funds target range at 3.50%–3.75% on 17 June 2026. The decision should be recorded with its date because the range can change at any scheduled or unscheduled meeting. A hold can still be hawkish or dovish depending on the statement, projections and expected path relative to market pricing.', 'FED', '17 June 2026'],
    ['How large were India’s foreign-exchange reserves in the RBI release for 17 July 2026?',
      'RBI weekly data put total reserves at US$676.237 billion, up US$1.080 billion from the previous week. Foreign-currency assets were US$551.057 billion; the balance included gold, SDR holdings and India’s reserve position in the IMF. Weekly dollar changes include both transactions and valuation effects from exchange-rate and gold-price movements.', 'RBI_WSS', 'Week ended 17 July 2026'],
    ['What did India’s provisional FY 2025–26 GDP estimate show?',
      'Under the new 2022–23 base-year series, real GDP was provisionally estimated at ₹323.12 lakh crore in FY 2025–26, growth of 7.7%; nominal GDP growth was 8.9%. Real GDP growth in Q4 was 7.8%. These are provisional estimates and should not be mixed with older-base series without a documented splice.', 'MOSPI_GDP', 'FY 2025–26 provisional estimate released 5 June 2026'],
    ['What is the difference between headline and core inflation?',
      'Headline inflation covers the full consumer basket, including food and energy. Core inflation is an analytical measure that excludes selected volatile components—most commonly food and energy—to reveal broader persistence; India’s official CPI release does not designate one universal “core CPI” series. For June 2026 the official combined headline CPI inflation was 4.38%, so any core figure must name its compiler and exclusion method.', 'MOSPI_CPI', 'June 2026'],
    ['How should a market-awareness card quote gold accurately?',
      'It must state the benchmark, currency, unit, fixing and date—for example, the LBMA Gold Price PM in U.S. dollars per troy ounce. “Gold is at X” is incomplete because Indian retail prices also reflect USD/INR, import duties, GST, local premia and purity. A futures settlement, London benchmark and Indian spot quote are different observations and should never be substituted for one another.', 'LBMA'],
    ['What was the dated Brent crude benchmark after the 24 July 2026 market close, and why did it matter for India?',
      'The actively traded Brent contract settled at US$96.78 per barrel on 24 July 2026 after touching higher levels amid Middle East supply risk. India is a large net crude importer, so a sustained oil rise can worsen the import bill and current account, pressure the rupee, raise fuel and logistics costs, and complicate inflation management. The exact domestic impact depends on taxes, retail pass-through and refining margins.', 'AP_MARKETS', '24 July 2026'],
  ],
);

addMany(
  ['ca_final_001', 'ca_final_002', 'ca_final_003', 'ca_final_004', 'ca_final_005',
    'ca_final_006', 'ca_final_007', 'ca_final_008', 'ca_final_009', 'ca_final_010',
    'ca_final_011', 'ca_final_012', 'ca_final_013', 'ca_final_014',
    'ca_final_020', 'ca_final_021', 'ca_final_022', 'ca_final_023', 'ca_final_024',
    'ca_final_025'],
  [
    ['Who led the Reserve Bank of India on 29 July 2026?',
      'Governor Sanjay Malhotra, who assumed office on 11 December 2024. He chaired the six-member Monetary Policy Committee, but each member had one vote and the published minutes recorded individual reasoning. Naming the officeholder without an as-of date is unsafe because the post changes.', 'RBI_GOVERNORS', '29 July 2026'],
    ['Who was India’s Finance Minister on 29 July 2026?',
      'Nirmala Sitharaman was Union Minister of Finance and Corporate Affairs. The Finance Ministry’s departments divide responsibility for economic policy, expenditure, revenue, financial services and public assets, so not every financial regulation is made personally by the minister.', 'DEA', '29 July 2026'],
    ['What is the core sequence of an IBC corporate resolution?',
      'A qualifying creditor or debtor files; NCLT admits the case and imposes a moratorium; an insolvency professional takes control and verifies claims; financial creditors form the CoC; plans are invited and evaluated; a plan approved by at least 66% voting share goes to NCLT. If no compliant plan succeeds, liquidation may follow.', 'IBBI'],
    ['Why is IL&FS a landmark Indian credit case?',
      'Its 2018 defaults showed how infrastructure delays, group complexity, leverage and short-term refinancing can create system-wide stress even when assets are long lived. Mutual funds and other lenders repriced NBFC risk, wholesale funding tightened and the government replaced the board. The case is fundamentally about governance plus asset–liability mismatch, not one bad project.', 'RBI_IBC', '2018'],
    ['Why is DHFL a landmark insolvency case?',
      'DHFL was the first financial-service provider taken through the specially notified IBC route after RBI initiated proceedings in 2019. Piramal Capital & Housing Finance’s resolution plan received NCLT approval in 2021. It demonstrated the need for regulator-led entry and tailored safeguards when resolving a lender rather than an ordinary industrial company.', 'IBBI', '2019–2021'],
    ['What is the cleanest way to compare PSU banks, private banks and NBFCs?',
      'First separate ownership from licence. PSU and private describe who owns a bank; both are banks with demand deposits, payment access and bank prudential rules. NBFC describes a different charter: it can provide credit and investment services but generally cannot accept demand deposits or issue cheques on itself. Then compare funding, governance, asset mix and regulation.', 'RBI_CURRENT'],
    ['What are the main Basel measures an Indian bank analyst should know?',
      'CET1, Tier 1 and total capital ratios measure capital against risk-weighted assets; the leverage ratio is a non-risk-based backstop; LCR covers a 30-day liquidity stress; NSFR covers one-year structural funding. Buffers include the 2.5% capital conservation buffer and any systemic or countercyclical add-ons implemented by RBI.', 'BASEL'],
    ['Which regulator should an Indian finance candidate associate with each major sector?',
      'RBI: banking, monetary policy and much of payments. SEBI: securities markets, funds and intermediaries. IRDAI: insurance. PFRDA: pension system and NPS. IBBI: insolvency professionals, agencies and information utilities under the IBC. IFSCA: financial activity in India’s IFSCs. Product structure and jurisdiction decide edge cases.', 'SEBI'],
    ['How do SEBI and the U.S. SEC compare?',
      'Both protect investors, regulate securities markets and require issuer and intermediary disclosure under their respective statutes. SEBI also has an explicit market-development mandate in India and operates within Indian company, exchange and financial-sector law; the SEC enforces U.S. federal securities law. Rules, filing forms, settlement systems and enforcement powers cannot be transferred from one jurisdiction to the other.', 'SEC'],
    ['How do the RBI and Federal Reserve differ?',
      'Both conduct monetary policy and support financial stability, but RBI also manages India’s currency issuance, reserves, payment systems and broad bank regulation under Indian statutes. The Federal Reserve combines a Board and twelve Reserve Banks, targets the federal-funds rate and shares U.S. bank oversight with other regulators. Their mandates, committee structures and operating frameworks differ.', 'FED'],
    ['Who was IMF Managing Director on 29 July 2026?',
      'Kristalina Georgieva. Her second five-year term began on 1 October 2024. The Managing Director chairs the IMF Executive Board and leads staff, but country lending and major policy decisions follow the Fund’s governance and Board procedures.', 'IMF_MD', '29 July 2026'],
    ['What is the practical difference between the IMF and World Bank?',
      'The IMF focuses on macroeconomic and external stability through surveillance, policy advice and balance-of-payments financing. The World Bank Group focuses on long-term development through sovereign projects, concessional finance, private-sector investment and guarantees. A country can work with both, but an IMF programme is not a World Bank infrastructure loan.', 'WORLD_BANK'],
    ['What does the BIS contribute to global finance?',
      'It provides a forum for central-bank cooperation, research and statistics, hosts committees including the Basel Committee and offers banking services to official institutions. Basel standards developed in this ecosystem become binding only when national authorities implement them. The BIS neither takes retail deposits nor directly supervises an Indian bank.', 'BIS'],
    ['What is the Financial Stability Board’s role?',
      'The FSB coordinates national financial authorities and international standard setters, monitors vulnerabilities and implementation, and develops recommendations on cross-border stability issues. It works by coordination, peer review and member implementation rather than directly licensing or fining firms. Its membership includes major economies and international bodies.', 'FSB'],
    ['Which company was the world’s largest by market capitalisation on 29 July 2026?',
      'Apple had reclaimed the top position at the 27 July close, near a US$5 trillion market value, after overtaking Nvidia. This fact was changing intraday during July, which is exactly why the card includes a date. Market capitalisation equals share price times shares outstanding and is not enterprise value, revenue or national economic size.', 'AXIOS_MARKET_CAP', '29 July 2026'],
    ['Which listed Indian company had the largest market capitalisation in late July 2026?',
      'Reliance Industries ranked first. A 24 July 2026 snapshot put its market capitalisation at about ₹17.22 lakh crore. The number moves with the share price and share count, so the defensible stable fact is the dated ranking and source—not a permanently fixed rupee value.', 'RIL_MARKET_CAP', '24 July 2026'],
    ['How do BSE and NSE differ?',
      'BSE, established in 1875, is India’s older exchange; NSE began electronic trading in the 1990s and became central to nationwide screen-based markets and derivatives. Both are SEBI-regulated market-infrastructure institutions with their own listing, trading and index businesses. Sensex belongs to BSE and Nifty 50 to NSE; a company may list on both.', 'SEBI'],
    ['Name the major exchange groups relevant to a global markets candidate.',
      'India: NSE and BSE. United States: NYSE and Nasdaq. Europe: London Stock Exchange Group, Euronext and Deutsche Börse. Asia: Japan Exchange Group, Hong Kong Exchanges and Clearing, Shanghai and Shenzhen exchanges, and Singapore Exchange. “Exchange” may mean the legal venue or its listed parent group, so identify which one the question requires.', 'SEBI'],
    ['Who are the “Big Four” professional-services networks?',
      'Deloitte, PwC, EY and KPMG. They are global networks of legally separate member firms providing audit and other professional services; they are not four single worldwide partnerships. Independence rules restrict which consulting services an audit firm may provide to an audit client.', 'SEBI'],
    ['Which Indian fintech business models should a finance candidate distinguish?',
      'Payments and merchant acquiring, digital lending and loan marketplaces, broking and wealth platforms, insurance distribution, account aggregation, KYC and regtech, and banking software are different models. Paytm, PhonePe, Razorpay, Zerodha, Groww and Policybazaar are not interchangeable “fintechs”: licences, revenue drivers, balance-sheet risk and unit economics differ.', 'RBI_CURRENT'],
  ],
);

addMany(
  ['gap_t15_01', 'gap_t15_02', 'gap_t15_03', 'gap_t15_04', 'gap_t15_05',
    'gap_t16_01', 'gap_t16_02',
    'gap_t19_01', 'gap_t19_02', 'gap_t19_03',
    'gap_t20_01', 'gap_t20_02',
    'gap_t21_01', 'gap_t21_02', 'gap_t21_03',
    'gap_t22_01', 'gap_t22_02',
    'gap_t28_01', 'gap_t28_02',
    'gap_t29_01', 'gap_t29_02', 'gap_t29_03',
    'int_gap_002', 'int_gap_003', 'int_gap_004'],
  [
    ['How does Red Sea disruption affect an Indian company’s financial statements?',
      'Longer routes can raise freight, fuel and insurance expense, delay inventory and increase goods in transit and working capital. If costs cannot be passed through, gross margin falls; if shortages halt production, revenue can also fall. Analysts should inspect Incoterms, hedges, inventory cover and route exposure before applying a blanket sector conclusion.', 'RBI_BOP'],
    ['How can renewed U.S.–China trade restrictions affect Indian markets?',
      'India may gain from supply-chain diversification and export substitution, but can also face weaker global demand, cheaper diverted imports and shortages of intermediate goods. Semiconductor and technology restrictions affect capex and productivity; tariffs affect volumes and prices. Map direct revenue, supplier, currency and policy exposure company by company.', 'IMF_WEO'],
    ['How does the Russia–Ukraine war transmit to Indian finance?',
      'Channels include crude, gas, fertiliser, food and metals prices; shipping and insurance; defence spending; payment routes; and sanctions compliance. Discounted imports can reduce one cost while external pressure raises another. The net effect depends on commodity mix, rupee movement, fiscal pass-through and geopolitical restrictions.', 'IMF_WEO'],
    ['Why do Federal Reserve decisions move Indian assets?',
      'They change U.S. yields, the dollar and global risk appetite. Higher expected U.S. rates can reduce the relative appeal of Indian assets, trigger portfolio outflows and pressure USD/INR; lower rates can reverse those channels. Domestic growth, inflation, valuation and RBI policy determine whether the textbook response actually occurs.', 'FED'],
    ['Why is the semiconductor cycle relevant to finance candidates?',
      'Semiconductors are cyclical because demand, inventories and fabrication capacity adjust with long lags, while leading-edge investment is capital intensive and technologically concentrated. AI accelerators can boom while consumer chips weaken. Analysts track end-market units, average selling price, utilisation, inventories, capex, foundry concentration and export controls—not one headline chip index.', 'SEBI'],
    ['What are the most reliable facts about India’s FY 2025–26 growth?',
      'MoSPI’s provisional new-base estimate was 7.7% real GDP growth, ₹323.12 lakh crore real GDP and 8.9% nominal growth; Q4 real growth was 7.8%. The base year is 2022–23. A forecast for FY 2026–27 is a different period and must not replace this outturn.', 'MOSPI_GDP', 'FY 2025–26'],
    ['How should “India reached a market-cap milestone” be verified?',
      'Define the universe—BSE-listed companies, NSE-listed companies or unique Indian issuers—then use the exchange’s dated aggregate market capitalisation and the same day’s FX rate for any U.S.-dollar conversion. Double-counting dual listings or mixing intraday equity value with a different FX close can create a false milestone.', 'BSE'],
    ['What is the National Pension System?',
      'NPS is a PFRDA-regulated defined-contribution retirement system in which contributions are invested under the subscriber’s chosen scheme and manager. Tier I is the primary pension account with regulated withdrawal rules and tax provisions; Tier II is optional and more liquid and requires an active Tier I account. Returns are market linked, not guaranteed.', 'PFRDA'],
    ['What was the EPF interest recommendation for FY 2025–26?',
      'The Central Board of Trustees recommended 8.25% for members’ accumulations for FY 2025–26, subject at the time of the official release to government approval and notification. “Recommended” and “credited” are different statuses, so the card does not present the recommendation as an already posted account entry.', 'EPFO', 'FY 2025–26 recommendation'],
    ['What was the PPF interest rate for July–September 2026?',
      'The Public Provident Fund rate remained 7.1% per year for Q2 FY 2026–27 under the government’s small-savings notification. PPF has a 15-year tenure, statutory contribution limits and tax rules; the administered rate is reviewed quarterly and should always be dated.', 'PPF', 'July–September 2026'],
    ['How do fundamental and technical analysis differ?',
      'Fundamental analysis estimates value from cash flows, financial position, industry economics, management and valuation. Technical analysis studies price, volume and market behaviour to infer trend or positioning. Both can be systematic, but neither guarantees return; a chart pattern does not replace solvency analysis, and a cheap multiple does not provide an entry catalyst.', 'SEBI'],
    ['How do top-down and bottom-up investing differ?',
      'Top-down starts with macroeconomics, countries, rates, currencies and sectors before selecting securities. Bottom-up starts with company economics and valuation, treating macro mainly as an input or risk. A robust process can combine them: a strong company can still be impaired by regulation, currency mismatch or an unsuitable portfolio-level exposure.', 'SEBI'],
    ['What is the difference between a spot and forward foreign-exchange rate?',
      'Spot is the rate for standard near-term settlement; a forward fixes today the rate for exchange on a future date. Forward points primarily reflect the two currencies’ interest-rate differential, adjusted for market basis and conventions. A forward premium is not a free expected return because funding costs offset the covered-interest differential.', 'RBI_BOP'],
    ['What do currency appreciation and depreciation mean for USD/INR?',
      'USD/INR is rupees per dollar. A move from 95 to 97 is rupee depreciation because more rupees buy one dollar; a move from 97 to 95 is appreciation. Exporter and importer effects depend on invoicing, imported inputs, hedging, demand elasticity and timing, so “weak currency always helps exporters” is too simple.', 'RBI_CURRENT'],
    ['How should an analyst explain a one-day rupee move?',
      'Decompose the global dollar, oil and import demand, portfolio and direct flows, hedging, fixing demand, local data and RBI operations. Then compare the move with forwards, volatility and peer currencies. A single causal headline is usually overconfident because several order flows clear simultaneously.', 'RBI_BOP'],
    ['What is the difference between a credit rating and an equity target price?',
      'A credit rating is an opinion on relative creditworthiness or expected ability to meet obligations under an agency scale. An equity target price is an analyst’s valuation estimate over a stated horizon. A company can be strong credit but unattractive equity if valuation is too high, or weak credit but high-upside equity because shareholders own a leveraged residual claim.', 'BASEL'],
    ['How should an interview candidate discuss a research “buy” call?',
      'State the valuation method, target horizon, expected total return, earnings assumptions, catalysts, downside risks and what would invalidate the thesis. A rating label is firm-specific and may be relative to the analyst’s coverage universe. It is not personal investment advice and should be separated from verified historical facts.', 'SEBI'],
    ['What is the difference between active and passive funds?',
      'An active fund’s manager selects and weights holdings to pursue its mandate, usually against a benchmark. A passive fund seeks to track an index before costs. Passive does not mean risk free, and active does not guarantee outperformance; compare mandate, expense ratio, tracking difference, turnover, concentration, capacity and tax impact.', 'SEBI'],
    ['How should an investor choose between an equity, debt, hybrid or index fund?',
      'Match the fund’s underlying risk and duration with the goal and horizon. Equity funds carry business and valuation risk; debt funds carry interest-rate, credit and liquidity risk; hybrid funds combine exposures; index funds inherit the index’s construction and concentration. The product label is only the start—read portfolio, benchmark, costs and exit terms.', 'SEBI'],
    ['What do Sharpe, Treynor and Sortino ratios measure?',
      'Sharpe equals excess return divided by total volatility; Treynor divides excess return by beta, assuming a diversified portfolio; Sortino divides excess return by downside deviation relative to a target. All depend on period, frequency and benchmark or target. They are not directly comparable when inputs or annualisation methods differ.', 'SEBI'],
    ['How do information ratio, alpha and beta differ?',
      'Information ratio is active return divided by tracking error against a benchmark. Alpha is model-dependent return unexplained by selected risk factors. Beta measures sensitivity to a chosen market factor. Each depends on benchmark, sample and estimation method; a high historical alpha can be noise or omitted-factor exposure.', 'SEBI'],
    ['Calculate and interpret a Sharpe ratio from a simple example.',
      'If annual portfolio return is 12%, the risk-free rate 5% and annualised volatility 10%, Sharpe = (12% − 5%)/10% = 0.70. It means 0.70 units of historical excess return per unit of total volatility under those inputs. It does not describe drawdown, skew, liquidity or future performance.', 'SEBI'],
    ['What is mutual-fund NAV?',
      'NAV per unit equals the market value of scheme assets plus receivables and accrued income minus liabilities and accrued expenses, divided by units outstanding. It is an accounting value per unit, not a measure of whether the fund is cheap. A ₹10 NAV fund is not inherently cheaper than a ₹100 NAV fund; returns depend on percentage change and distributions.', 'SEBI'],
    ['What is IRR, and when can it mislead?',
      'IRR solves for the discount rate that sets a cash-flow series’ NPV to zero. It can mislead with non-conventional cash flows that produce multiple IRRs, mutually exclusive projects of different scale, unrealistic reinvestment assumptions or omitted interim cash flows. NPV at the correct risk-adjusted discount rate is the safer value-creation test.', 'SEBI'],
    ['How should project IRR be compared with WACC?',
      'For conventional unlevered project cash flows, IRR above a project-appropriate WACC implies positive NPV; IRR below it implies negative NPV. The comparison is valid only when both use consistent currency, inflation, tax, leverage and risk. Equity IRR should instead be compared with cost of equity, not enterprise WACC.', 'SEBI'],
  ],
);

